void shinobi_logo_draw(u16 vramBase)
{
    VDP_loadTileData(shinobi_logo_tiles, vramBase, SHINOBI_LOGO_TILE_COUNT, DMA);
    for (u16 i = 0; i < 48; i++)
        VDP_setTileMapXY(BG_A, (u16)(vramBase + 1 + i),
                         14 + (i % 12), 10 + (i / 12));
}

static void roll_apply(void)
{
    for (u16 e = 2; e <= 10; e++)
        shinobi_logo_cram[e] =
            sheen_wave[(u16)(roll_step + 20 - (e - 2)) % 20];
}

void shinobi_palroll_reset(void)
{
    for (u16 i = 0; i < 16; i++) shinobi_logo_cram[i] = base_pal[i];
    roll_step = 0; roll_div = 0;
    roll_apply();
}

u16 shinobi_palroll_step(void)
{
    if (++roll_div < 4) return FALSE;
    roll_div = 0;
    roll_step = (roll_step + 1) % 20;
    roll_apply();
    return TRUE;
}
